const resumeMaster = $env.RESUME_MASTER_PROFILE || 'Set RESUME_MASTER_PROFILE env var';
const minScore = Number($env.AI_MATCH_THRESHOLD || 70);

return $input.all().map((item) => {
  const j = item.json;
  const prompt = [
    'You are a hiring-fit scoring engine. Output strict JSON only.',
    'Schema: {"match_score": number, "strengths": string[], "gaps": string[], "recommendation": string, "confidence": string}',
    `Minimum score gate is ${minScore}.`,
    `Candidate profile:\n${resumeMaster}`,
    `Job title: ${j.title || ''}`,
    `Company: ${j.company || j.company_name || ''}`,
    `Job description:\n${j.description || ''}`
  ].join('\n\n');

  j.ai_job_score_prompt = prompt;
  return { json: j };
});

const base = $('Build AI Scoring Prompt').item.json;
const content = $json.text || '{}';

let parsed;
try {
  const firstBrace = content.indexOf('{');
  const lastBrace = content.lastIndexOf('}');
  const jsonSlice = firstBrace >= 0 && lastBrace >= 0 ? content.slice(firstBrace, lastBrace + 1) : '{}';
  parsed = JSON.parse(jsonSlice);
} catch {
  parsed = { match_score: 0, strengths: [], gaps: ['json_parse_error'], recommendation: 'REVIEW_MANUALLY', confidence: 'low' };
}

return [{
  json: {
    ...base,
    ai_match_score: Number(parsed.match_score || 0),
    ai_match_reason: JSON.stringify({ strengths: parsed.strengths || [], gaps: parsed.gaps || [], recommendation: parsed.recommendation || '' }),
    ai_confidence: parsed.confidence || 'unknown'
  }
}];

const resumeLatex = $env.RESUME_LATEX_FULL || 'Set RESUME_LATEX_FULL env var';
const salutation = $env.COLDMAIL_SALUTATION || '[Name]';

return $input.all().map((item) => {
  const j = item.json;
  j.resume_tweaks_prompt = [
    'Return strict JSON only.',
    'Schema: {"summary_tweaks":[],"experience_tweaks":[],"skills_to_add":[],"ats_keywords":[],"important_notes":[]}',
    `Company: ${j.company || j.company_name || ''}`,
    `Role: ${j.title || ''}`,
    `Job description:\n${j.description || ''}`,
    `Resume LaTeX:\n${resumeLatex}`
  ].join('\n\n');

  j.coldmail_prompt = [
    'Write concise referral coldmail in plain text.',
    `Use salutation exactly as: ${salutation}`,
    `Company: ${j.company || j.company_name || ''}`,
    `Role: ${j.title || ''}`,
    `Candidate highlights: ${j.ai_match_reason || ''}`
  ].join('\n\n');

  return { json: j };
});

const base = $('Build Resume+Coldmail Prompt').item.json;
const resumeRaw = $('Message a model - Resume Tweaks').item.json.text || '{}';
const coldmail = $('Message a model - Coldmail').item.json.text || '';

let resumeParsed;
try {
  const firstBrace = resumeRaw.indexOf('{');
  const lastBrace = resumeRaw.lastIndexOf('}');
  const jsonSlice = firstBrace >= 0 && lastBrace >= 0 ? resumeRaw.slice(firstBrace, lastBrace + 1) : '{}';
  resumeParsed = JSON.parse(jsonSlice);
} catch {
  resumeParsed = { summary_tweaks: [], experience_tweaks: [], skills_to_add: [], ats_keywords: [], important_notes: ['json_parse_error'] };
}

return [{
  json: {
    ...base,
    ai_resume_tweaks: JSON.stringify(resumeParsed),
    ai_coldmail: coldmail,
    processed_for_ai: true,
    processed_for_resume: true,
    processed_for_coldmail: true,
    summarization_cycle_id: `${new Date().toISOString().slice(0,10)}_${$execution.id}`
  }
}];
